cssCode:
.badge-btn {
  width: 100px; height: 100px;
  background: radial-gradient(circle, #ffdf00, #daa520);
  border: 4px solid #fff; border-radius: 50%;
  box-shadow: 0 10px 20px rgba(218, 165, 32, 0.5);
  display: flex; align-items: center; justify-content: center;
  font-size: 40px; cursor: pointer;
  transition: transform 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.badge-btn.unlocked {
  animation: bounceUnlock 0.6s ease forwards;
  box-shadow: 0 0 40px #ffdf00, inset 0 0 20px #fff;
}
@keyframes bounceUnlock {
  0% { transform: scale(1); }
  50% { transform: scale(1.3) rotate(15deg); }
  100% { transform: scale(1.1) rotate(0deg); }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';
const badge = document.createElement('div');
badge.className = 'badge-btn';
badge.innerText = '🏆';
c.appendChild(badge);

badge.addEventListener('pointerdown', () => {
  badge.classList.remove('unlocked');
  void badge.offsetWidth; // રિસેટ એનિમેશન 
  badge.classList.add('unlocked');
});
